{"command": "create", "path": "/app/workspace/extract_receipts_v2.py", "file_text": """"Extract date and total amount from receipt images using Tesseract OCR."""
import os
import re
import datetime
from decimal import Decimal, InvalidOperation

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook


IMG_DIR = '/app/workspace/dataset/img'
OUT_XLSX = '/app/workspace/stat_ocr.xlsx'


# Priority order of total-indicating keywords. Lower priority number wins.
PRIORITY_KEYWORDS = [
    (1, ['GRAND TOTAL']),
    (2, ['TOTAL RM', 'TOTAL: RM']),
    (3, ['TOTAL AMOUNT']),
    (4, ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL',
         'TOTAL', 'AMOUNT']),
]
EXCLUSION_KEYWORDS = ['SUBTOTAL', 'SUB TOTAL', 'CASH TENDERED',
                      'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE']


def _kw_pattern(kw):
    """Build a regex for a keyword, allowing flexible whitespace and optional colon."""
    pat = re.escape(kw).replace(r'\ ', r'\s+').replace(r'\:', r'[:]?')
    return r'\b' + pat + r'\b'


_PRIORITY_RE = []
for prio, kws in PRIORITY_KEYWORDS:
    for kw in sorted(kws, key=len, reverse=True):
        _PRIORITY_RE.append((prio, kw, re.compile(_kw_pattern(kw), re.IGNORECASE)))

_EXCLUSION_RE = [(kw, re.compile(_kw_pattern(kw), re.IGNORECASE))
                 for kw in sorted(EXCLUSION_KEYWORDS, key=len, reverse=True)]

# "ROUNDING" when it's a standalone rounded-total line (not an adjustment line)
_ROUNDING_TOTAL_RE = re.compile(
    r'\bROUNDING\b(?!\s*(?:ADJ|ADJUSTMENT))', re.IGNORECASE)
# "ROUNDED" as a standalone keyword (e.g. "Rounded Total ...")
_ROUNDED_RE = re.compile(r'\bROUNDED\b', re.IGNORECASE)

# Cut-off marker for the "GST SUMMARY" block (also tolerates OCR variants).
_CUTOFF_RE = re.compile(r'\b(?:G[OS]T|BST)\s*SUMMARY\b|\bTAX\s+SUMMARY\b', re.IGNORECASE)

# A line that is just the GST portion of a total (e.g. "TOTAL INCLUDES 6% GST 0.48")
_GST_PORTION_RE = re.compile(r'\d+\s*%\s*GST\s+[\d,]*[\.,]\d{2}\s*$', re.IGNORECASE)

# Number pattern: 2 decimals, dot or comma as decimal, optional thousand separators
_NUMBER_RE = re.compile(r'-?\d{1,3}(?:,\d{3})+\.\d{1,2}|-?\d+[.,]\d{2}')


def ocr_passes(image_path):
    img = Image.open(image_path)
    gray = ImageOps.grayscale(img)
    big2 = gray.resize((gray.width * 2, gray.height * 2), Image.Resampling.LANCZOS)
    big3 = gray.resize((gray.width * 3, gray.height * 3), Image.Resampling.LANCZOS)
    variants = [
        (gray, '--psm 6'),
        (ImageOps.autocontrast(gray), '--psm 6'),
        (gray.filter(ImageFilter.SHARPEN), '--psm 6'),
        (ImageOps.autocontrast(big2), '--psm 6'),
        (big2.filter(ImageFilter.SHARPEN), '--psm 6'),
        (big3.filter(ImageFilter.SHARPEN), '--psm 6'),
        (ImageOps.autocontrast(gray), '--psm 4'),
    ]
    for v, psm in variants:
        try:
            yield pytesseract.image_to_string(v, config=psm)
        except Exception:
            continue


def extract_date(texts):
    patterns = [
        (re.compile(r'(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)'), 'dmy4'),
        (re.compile(r'(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)'), 'ymd'),
        (re.compile(r'(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)'), 'dmy2'),
        (re.compile(r'\b(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(\d{4})\b', re.I), 'dmy_text'),
    ]
    months_map = {'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
                  'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12}

    candidates = []
    for text in texts:
        for pat, kind in patterns:
            for m in pat.finditer(text):
                try:
                    if kind == 'dmy4':
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == 'ymd':
                        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == 'dmy2':
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                        y = 2000 + y if y < 70 else 1900 + y
                    else:
                        d = int(m.group(1))
                        mo = months_map[m.group(2).upper()[:3]]
                        y = int(m.group(3))
                except (ValueError, KeyError):
                    continue
                if mo > 12 and d <= 12:
                    d, mo = mo, d
                if not (1 <= mo <= 12 and 1 <= d <= 31 and 2010 <= y <= 2030):
                    continue
                try:
                    datetime.date(y, mo, d)
                except ValueError:
                    continue
                candidates.append((y, mo, d))

    if not candidates:
        return None

    counts = {}
    first_seen = {}
    for idx, c in enumerate(candidates):
        counts[c] = counts.get(c, 0) + 1
        first_seen.setdefault(c, idx)
    best = max(counts.items(), key=lambda kv: (kv[1], -first_seen[kv[0]]))[0]
    y, mo, d = best
    return f"{y:04d}-{mo:02d}-{d:02d}"


def _parse_amount(num_str):
    s = num_str.lstrip('-')
    if '.' in s and ',' in s:
        s = s.replace(',', '')
    elif ',' in s:
        parts = s.rsplit(',', 1)
        if len(parts[1]) == 2:
            s = parts[0].replace(',', '') + '.' + parts[1]
        else:
            s = s.replace(',', '')
    try:
        v = Decimal(s)
    except InvalidOperation:
        return None
    if v <= 0:
        return None
    return v


def _primary_match(line):
    """Return (match_start, is_exclusion, prio, keyword) for the leftmost
    priority or exclusion keyword in the line, or None."""
    best = None
    for prio, kw, rx in _PRIORITY_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), False, prio, kw, m.end())
    for kw, rx in _EXCLUSION_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), True, None, kw, m.end())
    # Also consider ROUNDED / standalone ROUNDING as low priority (prio 4)
    for rx, kw in [(_ROUNDED_RE, 'ROUNDED'), (_ROUNDING_TOTAL_RE, 'ROUNDING')]:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), False, 4, kw, m.end())
    return best


def find_total(text):
    raw_lines = text.split('\n')
    # Cut off at the "GST SUMMARY" table header
    cutoff = len(raw_lines)
    for i, ln in enumerate(raw_lines):
        if _CUTOFF_RE.search(ln):
            cutoff = i
            break
    lines = raw_lines[:cutoff]

    rounding_rx = re.compile(r'\bROUND(?:ING|ED)?\b', re.I)
    rounding_lines = [i for i, ln in enumerate(lines) if rounding_rx.search(ln)]

    candidates = []  # (prio, line_idx, value, keyword)
    for i, line in enumerate(lines):
        pm = _primary_match(line)
        if pm is None:
            continue
        start, is_excl, prio, kw, end = pm
        if is_excl:
            continue
        # Skip lines that are clearly the GST portion of a total
        if _GST_PORTION_RE.search(line):
            continue
        after = line[end:]
        nums = _NUMBER_RE.findall(after)
        value = None
        if nums:
            value = _parse_amount(nums[-1])
        if value is None:
            # Fallback: last number on the next non-empty line
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                if not nxt.strip():
                    continue
                nxt_nums = _NUMBER_RE.findall(nxt)
                if nxt_nums:
                    value = _parse_amount(nxt_nums[-1])
                break
        if value is None:
            continue
        candidates.append((prio, i, value, kw.upper()))

    if not candidates:
        return None

    # Prefer candidates that appear after a rounding line (final rounded total)
    if rounding_lines:
        last_round = max(rounding_lines)
        after_round = [c for c in candidates if c[1] > last_round]
        if after_round:
            candidates = after_round

    candidates.sort(key=lambda c: (c[0], -c[1]))
    return f"{candidates[0][2]:.2f}"


def find_total_multi(texts):
    counts = {}
    order = []
    for t in texts:
        v = find_total(t)
        if v is not None:
            if v not in counts:
                counts[v] = 0
                order.append(v)
            counts[v] += 1
    if not counts:
        return None
    return max(order, key=lambda v: (counts[v], -order.index(v)))


def process_image(path):
    texts = list(ocr_passes(path))
    date = extract_date(texts)
    total = find_total_multi(texts)
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        print(f"{fname}: date={date} total={total}")
        ws.append([fname, date, total])
    wb.save(OUT_XLSX)
    print(f"\nSaved -> {OUT_XLSX}")


if __name__ == '__main__':
    main()
