import os
import re
import datetime
from decimal import Decimal, InvalidOperation

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook


IMG_DIR = '/app/workspace/dataset/img'
OUT_XLSX = '/app/workspace/stat_ocr.xlsx'


PRIORITY_KEYWORDS = [
    (1, ['GRAND TOTAL']),
    (2, ['TOTAL RM', 'TOTAL: RM']),
    (3, ['TOTAL AMOUNT']),
    (4, ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL',
         'TOTAL', 'AMOUNT']),
]
EXCLUSION_KEYWORDS = ['SUBTOTAL', 'SUB TOTAL', 'CASH TENDERED',
                      'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE']

# Compile keyword regexes once, with longest-first ordering within each list
_PRIORITY_RE = []
for prio, kws in PRIORITY_KEYWORDS:
    for kw in sorted(kws, key=len, reverse=True):
        pattern = r'\b' + kw.replace(' ', r'\s+').replace(':', r'[:]?') + r'\b'
        _PRIORITY_RE.append((prio, kw, re.compile(pattern, re.IGNORECASE)))

_EXCLUSION_RE = []
for kw in sorted(EXCLUSION_KEYWORDS, key=len, reverse=True):
    pattern = r'\b' + kw.replace(' ', r'\s+') + r'\b'
    _EXCLUSION_RE.append((kw, re.compile(pattern, re.IGNORECASE)))


def ocr_passes(image_path):
    """Yield OCR text from several preprocessing + PSM variants."""
    img = Image.open(image_path)
    gray = ImageOps.grayscale(img)
    big = gray.resize((gray.width * 2, gray.height * 2), Image.Resampling.LANCZOS)
    variants = [
        (gray, '--psm 6'),
        (ImageOps.autocontrast(gray), '--psm 6'),
        (gray.filter(ImageFilter.SHARPEN), '--psm 6'),
        (ImageOps.autocontrast(big), '--psm 6'),
        (ImageOps.autocontrast(gray), '--psm 4'),
    ]
    for v, psm in variants:
        try:
            yield pytesseract.image_to_string(v, config=psm)
        except Exception:
            continue


def extract_date(texts):
    """Return date in YYYY-MM-DD, trying several patterns across OCR passes."""
    patterns = [
        # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
        (re.compile(r'(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})(?!\d)'), 'dmy4'),
        # YYYY-MM-DD, YYYY/MM/DD
        (re.compile(r'(?<!\d)(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)'), 'ymd'),
        # DD/MM/YY, DD-MM-YY
        (re.compile(r'(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)'), 'dmy2'),
        # D MMM YYYY
        (re.compile(r'\b(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(\d{4})\b', re.I), 'dmy_text'),
    ]
    months_map = {'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
                  'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12}

    candidates = []  # list of (y, m, d)
    for text in texts:
        for pat, kind in patterns:
            for m in pat.finditer(text):
                try:
                    if kind == 'dmy4':
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == 'ymd':
                        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == 'dmy2':
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                        y = 2000 + y if y < 70 else 1900 + y
                    else:
                        d = int(m.group(1))
                        mo = months_map[m.group(2).upper()[:3]]
                        y = int(m.group(3))
                except (ValueError, KeyError):
                    continue
                # Fix impossible day/month swaps
                if mo > 12 and d <= 12:
                    d, mo = mo, d
                if not (1 <= mo <= 12 and 1 <= d <= 31):
                    continue
                if not (2010 <= y <= 2030):
                    continue
                try:
                    datetime.date(y, mo, d)
                except ValueError:
                    continue
                candidates.append((y, mo, d))

    if not candidates:
        return None

    # Pick the most frequent candidate across OCR passes
    counts = {}
    for c in candidates:
        counts[c] = counts.get(c, 0) + 1
    best = max(counts.items(), key=lambda kv: (kv[1], -candidates.index(kv[0])))[0]
    y, mo, d = best
    return f"{y:04d}-{mo:02d}-{d:02d}"


_NUMBER_RE = re.compile(r'-?\d{1,3}(?:,\d{3})*\.\d{2}|-?\d+\.\d{2}')


def _parse_amount(num_str):
    s = num_str.replace(',', '').lstrip('-')
    try:
        v = Decimal(s)
    except InvalidOperation:
        return None
    if v <= 0:
        return None
    return v


def _primary_match(line):
    """Return (match_start, priority_or_None, keyword) for the leftmost
    priority or exclusion keyword in the line, or None if no match."""
    best = None  # (start, is_exclusion, prio, kw)
    for prio, kw, rx in _PRIORITY_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), False, prio, kw)
    for kw, rx in _EXCLUSION_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), True, None, kw)
    return best


def find_total(text):
    """Find the total amount in OCR text following the keyword hierarchy."""
    lines = text.split('\n')
    # Identify rounding-indicator line indices (used for tie-breaking)
    rounding_rx = re.compile(r'\bROUND(?:ING|ED)?\b', re.I)
    rounding_lines = [i for i, ln in enumerate(lines) if rounding_rx.search(ln)]

    candidates = []  # (prio, line_idx, value)
    for i, line in enumerate(lines):
        pm = _primary_match(line)
        if pm is None:
            continue
        start, is_excl, prio, kw = pm
        if is_excl:
            continue
        # Extract numeric value from this line, after the keyword
        after = line[start + len(kw):]
        nums = _NUMBER_RE.findall(after)
        value = None
        if nums:
            value = _parse_amount(nums[-1])
        if value is None:
            # Fallback: last number on the next non-empty line
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                if not nxt.strip():
                    continue
                nxt_nums = _NUMBER_RE.findall(nxt)
                if nxt_nums:
                    value = _parse_amount(nxt_nums[-1])
                break
        if value is None:
            continue
        candidates.append((prio, i, value, kw.upper()))

    if not candidates:
        return None

    # Prefer candidates that appear after any rounding line
    if rounding_lines:
        last_round = max(rounding_lines)
        after_round = [c for c in candidates if c[1] > last_round]
        if after_round:
            candidates = after_round

    # Highest priority (lowest number); within same priority, prefer the last line
    candidates.sort(key=lambda c: (c[0], -c[1]))
    best = candidates[0]
    return f"{best[2]:.2f}"


def find_total_multi(texts):
    """Aggregate total extraction across OCR passes, pick most frequent."""
    counts = {}
    order = []
    for t in texts:
        v = find_total(t)
        if v is not None:
            if v not in counts:
                counts[v] = 0
                order.append(v)
            counts[v] += 1
    if not counts:
        return None
    return max(order, key=lambda v: (counts[v], -order.index(v)))


def process_image(path):
    texts = list(ocr_passes(path))
    date = extract_date(texts)
    total = find_total_multi(texts)
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        print(f"{fname}: date={date} total={total}")
        ws.append([fname, date, total])
    wb.save(OUT_XLSX)
    print(f"\nSaved -> {OUT_XLSX}")


if __name__ == '__main__':
    main()
