    counts = {}
    order = []
    for t in texts:
        v = find_total(t)
        if v is not None:
            if v not in counts:
                counts[v] = 0
                order.append(v)
            counts[v] += 1
    if not counts:
        return None
    return max(order, key=lambda v: (counts[v], -order.index(v)))


def process_image(path):
    texts = list(ocr_passes(path))
    date = extract_date(texts)
    total = find_total_multi(texts)
    return date, total


def main():
