def _parse_amount(num_str):
    s = num_str.lstrip('-')
    if '.' in s and ',' in s:
        s = s.replace(',', '')
    elif ',' in s:
        parts = s.rsplit(',', 1)
        if len(parts[1]) == 2:
            s = parts[0].replace(',', '') + '.' + parts[1]
        else:
