    return v


def _primary_match(line):
    """Return (match_start, priority_or_None, keyword) for the leftmost
    priority or exclusion keyword in the line, or None if no match."""
    best = None  # (start, is_exclusion, prio, kw)
    for prio, kw, rx in _PRIORITY_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
