    for kw, rx in _EXCLUSION_RE:
        m = rx.search(line)
        if m and (best is None or m.start() < best[0]):
            best = (m.start(), True, None, kw)
    return best


def find_total(text):
    """Find the total amount in OCR text following the keyword hierarchy."""
    lines = text.split('\n')
    # Identify rounding-indicator line indices (used for tie-breaking)
    rounding_rx = re.compile(r'\bROUND(?:ING|ED)?\b', re.I)
    rounding_lines = [i for i, ln in enumerate(lines) if rounding_rx.search(ln)]

    candidates = []  # (prio, line_idx, value)
    for i, line in enumerate(lines):
        pm = _primary_match(line)
        if pm is None:
            continue
        start, is_excl, prio, kw = pm
        if is_excl:
            continue
        # Extract numeric value from this line, after the keyword
        after = line[start + len(kw):]
        nums = _NUMBER_RE.findall(after)
        value = None
        if nums:
            value = _parse_amount(nums[-1])
        if value is None:
            # Fallback: last number on the next non-empty line
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                if not nxt.strip():
                    continue
                nxt_nums = _NUMBER_RE.findall(nxt)
                if nxt_nums:
                    value = _parse_amount(nxt_nums[-1])
