        after_round = [c for c in candidates if c[1] > last_round]
        if after_round:
            candidates = after_round

    # Highest priority (lowest number); within same priority, prefer the last line
    candidates.sort(key=lambda c: (c[0], -c[1]))
    best = candidates[0]
    return f"{best[2]:.2f}"


def find_total_multi(texts):
    """Aggregate total extraction across OCR passes, pick most frequent."""
    counts = {}
    order = []
    for t in texts:
        v = find_total(t)
        if v is not None:
            if v not in counts:
